fn concat(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Pre-allocate enough space for both vectors to avoid multiple reallocations.
    let total_len = a.len() + b.len();
    let mut c = Vec::with_capacity(total_len);

    // Move all elements from `a` into `c`
    c.extend(a);

    // Then move all elements from `b` into `c`
    c.extend(b);

    c
}

